'use strict';
const fs=require('node:fs'),fsp=require('node:fs/promises'),path=require('node:path'),os=require('node:os');
function enlargerInfo(){let ready=false;try{ready=fs.statSync(path.join(__dirname,'ai-models','super-resolution-10.onnx')).size>0&&fs.existsSync(path.join(path.dirname(require.resolve('onnxruntime-web')),'ort-wasm-simd-threaded.wasm'));}catch{}return{id:'ai-enlarger',name:'AI Image Enlarger',version:'1.0.0',author:'Pigeon',category:'Image editing',kind:'builtin',bundled:true,installed:true,enabled:true,modelReady:ready,status:ready?'ready':'error',statusDetail:ready?'Bundled CPU runtime and model are available. No Python, installation, or service is required. Test the engine to verify inference.':'Bundled AI files are missing. Repair or reinstall Pigeon from a verified package.',description:'Built-in offline 2×/3× image enlargement using a sub-pixel convolutional neural network.',configured:{},configSchema:[],model:{name:'ONNX Super Resolution CNN',type:'Image super-resolution (not an LLM)',size:'235 KB',purpose:'Enlarge images locally by 2× or 3×.',source:'ONNX Model Zoo · bundled with Pigeon',license:'Apache-2.0'},modelState:{status:'bundled',ready},logs:[]};}
async function testEnlarger(){const directory=await fsp.mkdtemp(path.join(os.tmpdir(),'pigeon-ai-check-'));try{const sharp=require('sharp'),source=await sharp({create:{width:16,height:16,channels:3,background:'#6688aa'}}).png().toBuffer(),target=path.join(directory,'test.png'),result=await require('./ai-enlarger').enlargeImageWithAi(source,target,{scale:2});if(result.width!==32||result.height!==32)throw Error('Unexpected AI output dimensions');return{ok:true,detail:'Bundled CPU engine passed real ONNX inference (16×16 → 32×32). No Python or service required.'};}catch(error){return{ok:false,detail:`AI engine check failed: ${error.message}. Retry to start a fresh worker; if bundled files are damaged, repair/reinstall Pigeon.`};}finally{await fsp.rm(directory,{recursive:true,force:true});}}
module.exports={enlargerInfo,testEnlarger};
